(* [comment removed for export] *)
Definition nstore_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (N h : Z) (lnk : word) (SSB tot sz lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                  t3' t4' t5' t6') F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(N, N + 16); (s_total, s_total + 8); (s_stored0, s_stored0 + 4); (SSB + 8 * tot, SSB + 8 * (tot + sz + 1));
             (bv_unsigned sp - 112, bv_unsigned sp)]%Z m m'
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' N [C8 (Z_to_bv 64 h); C4 lnk; C4 (Z_to_bv 64 (tot + 1))]
    /\ rw_cells asegs m' s_total [C8 (Z_to_bv 64 (tot + sz + 1))]
    /\ rw_cells asegs m' s_stored0 [C4 (Z_to_bv 64 (tot + sz + 1))]
    /\ stk asegs m' (SSB + 8 * (tot + sz + 1)) (SSB + 2 ^ 23)
    /\ stk asegs m' lo (bv_unsigned sp).

(* [comment removed for export] *)
Lemma nstore_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (N h SSB tot ARGS TR lo : Z) (ws rest : list word) (x lnk y : word),
  (1 <= Z.of_nat (length ws) <= 254)%Z -> (0 <= tot)%Z -> (tot + Z.of_nat (length ws) + 1 < 2^20)%Z -> (0 <= h < 2^64)%Z ->
  (0x66f000 <= SSB)%Z -> (SSB + 2^23 <= lo)%Z -> (0x66f000 <= N)%Z -> (N + 16 <= lo)%Z ->
  (N + 16 <= SSB \/ SSB + 2^23 <= N)%Z ->
  rw_cells asegs m N [C8 x; C4 lnk; C4 y] ->
  rw_cells asegs m s_total [C8 (Z_to_bv 64 tot)] -> rw_cells asegs m s_data0 [C8 (Z_to_bv 64 SSB)] ->
  rw_cells asegs m s_stored0 [C4 (Z_to_bv 64 tot)] -> stk asegs m (SSB + 8 * tot) (SSB + 2 ^ 23) ->
  rw_cells asegs m ARGS [C8 (Z_to_bv 64 TR); C4 (Z_to_bv 64 (Z.of_nat (length ws))); C4 (Z_to_bv 64 0)] ->
  u64arr asegs m TR (ws ++ rest) ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 112)%Z ->
  (bv_unsigned sp <= ARGS)%Z -> (ARGS + 16 <= TR)%Z -> (TR + 8 * Z.of_nat (length (ws ++ rest)) <= 2^63)%Z ->
  mem_inv asegs m ->
  evt asegs (nstore_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc N h lnk SSB tot (Z.of_nat (length ws)) lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 N) a1 (Z_to_bv 64 ARGS) (Z_to_bv 64 h) a4 a5 a6 a7 s2 s3 s4 s5 s6
             s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 nstore_entry) fc None m (seg_rom asegs)).
Proof.
